<template><article class="ink-panel metric-card"><header><h2>{{ title }}</h2><span>{{ sample }} 样本</span></header><p v-if="sample === 0" class="no-sample">无样本，不等同于数值为零。</p><dl v-else><div v-for="([label,value]) in items" :key="label"><dt>{{ label }}</dt><dd>{{ value }}</dd><span class="bar" :style="{ '--metric-bar': `${barWidth(value)}%` }" aria-hidden="true" /></div></dl><footer v-if="footer">{{ footer }}</footer></article></template>
<script setup>
const props=defineProps({title:{type:String,required:true},sample:{type:Number,default:0},items:{type:Array,default:()=>[]},footer:{type:String,default:''}})
function barWidth(value){const number=Number(value);if(!Number.isFinite(number)||number<=0)return 0;const max=Math.max(1,...props.items.map(item=>Number(item[1])).filter(Number.isFinite));return Math.max(4,Math.round(number/max*100))}
</script>
<style scoped>.ink-panel{padding:var(--ink-sp-16);background:var(--ink-wash-panel);border:1px solid var(--line-soft);border-radius:var(--ink-radius-paper);box-shadow:var(--ink-shadow-panel)}header{display:flex;justify-content:space-between;gap:var(--ink-sp-8)}h2{margin:0;font-family:var(--ink-font-display);font-size:var(--ink-fs-18)}header span,dt,.no-sample,footer{color:var(--ink-muted);font-size:var(--ink-fs-12)}dl{display:grid;gap:var(--ink-sp-12);margin:var(--ink-sp-16) 0 0}dl div{display:grid;grid-template-columns:1fr auto;gap:var(--ink-sp-4)}dd{margin:0;color:var(--ink-strong);font-family:var(--ink-font-code)}.bar{grid-column:1/-1;height:4px;background:linear-gradient(90deg,var(--mineral-cyan) var(--metric-bar),var(--surface-muted) var(--metric-bar))}footer{margin-top:var(--ink-sp-12)}</style>
